(function () {
  'use strict';
  var box = document.getElementById('q'), out = document.getElementById('results');
  if (!box || !out) return;
  var D = {'\u0105':'a','\u0107':'c','\u0119':'e','\u0142':'l','\u0144':'n','\u00f3':'o','\u015b':'s','\u017a':'z','\u017c':'z'};
  function norm(s) { return String(s || '').toLowerCase().replace(/[\u0105\u0107\u0119\u0142\u0144\u00f3\u015b\u017a\u017c]/g, function (c) { return D[c] || c; }); }
  function cell(text) { var el = document.createElement('td'); el.textContent = text; return el; }
  box.addEventListener('input', function () {
    var words = norm(box.value.trim()).split(/\s+/).filter(function (w) { return w; });
    out.textContent = '';
    if (words.length < 1) return;
    var hits = window.SEARCH_INDEX.filter(function (e) {
      var hay = norm(e.t + ' ' + (e.d || ''));
      return words.every(function (w) {
        var stem = w.slice(0, Math.min(w.length, 6));
        return hay.split(/[^a-z0-9]+/).some(function (t) { return t.indexOf(stem) === 0; });
      });
    }).slice(0, 20);
    if (!hits.length) {
      var p = document.createElement('p');
      p.className = 'muted';
      p.textContent = 'Brak wyników.';
      out.appendChild(p);
      return;
    }
    hits.forEach(function (e) {
      var card = document.createElement('div');
      card.className = 'card';
      var a = document.createElement('a');
      a.href = e.u;
      a.textContent = e.t;
      var meta = document.createElement('span');
      meta.className = 'small muted';
      meta.textContent = ' ' + (e.k || '');
      card.appendChild(a);
      card.appendChild(meta);
      if (e.d) {
        var d = document.createElement('div');
        d.className = 'small muted';
        d.textContent = String(e.d).slice(0, 140);
        card.appendChild(d);
      }
      out.appendChild(card);
    });
  });
})();